        if ch.isspace() or ch == ",":
            i += 1
            continue
        if ch in "'\"":
            quote = ch
            start = i
            i += 1
            escape = False
            while i < len(text):
                c = text[i]
                if escape:
                    escape = False
                elif c == "\\" and quote == '"':
                    escape = True
                elif c == quote:
                    i += 1
                    break
                i += 1
            else:
                raise NuError(f"expected closing {quote}", "nu::parser::parse_mismatch")
            tokens.append(Token("string", unquote(text[start:i])))
            continue
        raw = re.match(r"r(#+)'", text[i:])
        if raw:
            hashes = raw.group(1)
            start = i + 2 + len(hashes)
            end_pat = "'" + hashes
            end = text.find(end_pat, start)
            if end < 0:
                raise NuError(f"expected closing '{hashes}", "nu::parser::parse_mismatch")
            tokens.append(Token("string", text[start:end]))
            i = end + len(end_pat)
            continue
